define(["core/ajax","core/notification"],function(Ajax,Notification){const formatTime=seconds=>{seconds=Math.max(0,Math.round(Number(seconds)||0));const hours=Math.floor(seconds/3600);const minutes=Math.floor(seconds%3600/60);const secs=seconds%60;const two=value=>String(value).padStart(2,"0");return hours>0?`${two(hours)}:${two(minutes)}:${two(secs)}`:`${two(minutes)}:${two(secs)}`};const loadScript=(url,ready)=>new Promise((resolve,reject)=>{if(ready()){resolve();return}const found=document.querySelector(`script[src="${url}"]`);if(found){const timer=window.setInterval(()=>{if(ready()){window.clearInterval(timer);resolve()}},100);window.setTimeout(()=>{window.clearInterval(timer);if(!ready()){reject(new Error(`Unable to load ${url}`))}},1e4);return}const script=document.createElement("script");script.src=url;script.async=true;script.onload=()=>ready()?resolve():reject(new Error(`Unable to initialise ${url}`));script.onerror=reject;document.head.appendChild(script)});const html5Adapter=(video,maxrate)=>{if(maxrate>0){video.addEventListener("ratechange",()=>{if(video.playbackRate>maxrate){video.playbackRate=maxrate}})}return Promise.resolve({currentTime:()=>Promise.resolve(video.currentTime||0),duration:()=>Promise.resolve(Number.isFinite(video.duration)?video.duration:0),seek:time=>{video.currentTime=Math.max(0,time);return Promise.resolve()},playing:()=>Promise.resolve(!video.paused&&!video.ended),onTime:callback=>video.addEventListener("timeupdate",callback)})};const youtubeAdapter=(container,maxrate)=>new Promise((resolve,reject)=>{const videoid=container.dataset.videoid;const initialise=()=>{const player=new window.YT.Player(container.id,{videoId:videoid,playerVars:{rel:0,playsinline:1},events:{onReady:()=>resolve({currentTime:()=>Promise.resolve(player.getCurrentTime()||0),duration:()=>Promise.resolve(player.getDuration()||0),seek:time=>{player.seekTo(Math.max(0,time),true);return Promise.resolve()},playing:()=>Promise.resolve(player.getPlayerState()===window.YT.PlayerState.PLAYING),onTime:callback=>window.setInterval(callback,1e3)}),onPlaybackRateChange:event=>{if(maxrate>0&&event.data>maxrate){player.setPlaybackRate(maxrate)}}}})};if(window.YT&&window.YT.Player){initialise();return}const previous=window.onYouTubeIframeAPIReady;window.onYouTubeIframeAPIReady=()=>{if(typeof previous==="function"){previous()}initialise()};loadScript("https://www.youtube.com/iframe_api",()=>Boolean(window.YT&&window.YT.Player)).catch(reject)});const vimeoAdapter=(iframe,maxrate)=>loadScript("https://player.vimeo.com/api/player.js",()=>Boolean(window.Vimeo&&window.Vimeo.Player)).then(()=>{const player=new window.Vimeo.Player(iframe);if(maxrate>0){player.on("playbackratechange",event=>{if(event.playbackRate>maxrate){player.setPlaybackRate(maxrate).catch(()=>{})}})}return{currentTime:()=>player.getCurrentTime(),duration:()=>player.getDuration(),seek:time=>player.setCurrentTime(Math.max(0,time)).then(()=>undefined),playing:()=>player.getPaused().then(paused=>!paused),onTime:callback=>player.on("timeupdate",callback)}});const getAdapter=root=>{const maxrate=Number(root.dataset.maxplaybackrate||0);const html5=document.getElementById("videomarker-html5");if(html5){return html5Adapter(html5,maxrate)}const youtube=document.getElementById("videomarker-youtube");if(youtube){return youtubeAdapter(youtube,maxrate)}const vimeo=document.getElementById("videomarker-vimeo");if(vimeo){return vimeoAdapter(vimeo,maxrate)}return Promise.reject(new Error("No supported player was found."))};const createSelectedRow=(question,mark,index,removeHandler)=>{const row=document.createElement("div");row.className="videomarker-selected-item";const text=document.createElement("span");text.textContent=mark.end===null?`${index+1}. ${formatTime(mark.start)}`:`${index+1}. ${formatTime(mark.start)} – ${formatTime(mark.end)}`;const remove=document.createElement("button");remove.type="button";remove.className="btn btn-sm btn-outline-danger";remove.textContent="×";remove.addEventListener("click",removeHandler);row.append(text,remove);return row};const initialiseQuestion=(root,question,adapter)=>{const required=Number(question.dataset.requiredcount||1);const type=question.dataset.type;const selectedContainer=question.querySelector('[data-role="selected"]');const selectedCount=question.querySelector('[data-role="selectedcount"]');const submit=question.querySelector('[data-action="submit"]');const feedback=question.querySelector('[data-role="feedback"]');const markButton=question.querySelector(type==="point"?'[data-action="mark-point"]':'[data-action="mark-interval"]');const intervalLabel=question.querySelector('[data-role="interval-label"]');let selected=[];let intervalStart=null;const render=()=>{if(!selectedContainer){return}selectedContainer.replaceChildren();selected.forEach((mark,index)=>{selectedContainer.appendChild(createSelectedRow(question,mark,index,()=>{selected.splice(index,1);render()}))});selectedCount.textContent=String(selected.length);submit.disabled=selected.length!==required};if(markButton){markButton.addEventListener("click",()=>{adapter.currentTime().then(time=>{if(selected.length>=required){return}if(type==="point"){selected.push({start:time,end:null});render();return}if(intervalStart===null){intervalStart=time;if(intervalLabel){intervalLabel.textContent="■ "+formatTime(time)}return}const start=Math.min(intervalStart,time);const end=Math.max(intervalStart,time);selected.push({start:start,end:end});intervalStart=null;if(intervalLabel){intervalLabel.textContent=markButton.dataset.defaultLabel||"Start interval"}render()}).catch(Notification.exception)});if(intervalLabel){markButton.dataset.defaultLabel=intervalLabel.textContent}}if(submit){submit.addEventListener("click",()=>{if(selected.length!==required){return}submit.disabled=true;Ajax.call([{methodname:"mod_videomarker_save_answer",args:{cmid:Number(root.dataset.cmid),questionid:Number(question.dataset.questionid),marksjson:JSON.stringify(selected)}}])[0].then(result=>{feedback.textContent=`${result.correctcount}/${result.markcount} — ${Number(result.score).toFixed(2)}/${Number(result.maxscore).toFixed(2)}`;if(result.feedback){const detail=document.createElement("div");detail.textContent=result.feedback;feedback.appendChild(detail)}selected=[];render();if(result.locked){question.classList.add("is-locked");if(markButton){markButton.disabled=true}submit.disabled=true}}).catch(error=>{submit.disabled=false;Notification.exception(error)})})}};const init=()=>{const root=document.getElementById("videomarker-root");if(!root){return}getAdapter(root).then(adapter=>{const cmid=Number(root.dataset.cmid);const allowseek=Number(root.dataset.allowseek)===1;const resume=Number(root.dataset.resume)===1;let maxwatched=Number(root.dataset.maxwatched||0);const lastposition=Number(root.dataset.lastposition||0);const progressValue=document.getElementById("videomarker-progress-value");const progressFill=document.getElementById("videomarker-progressbar-fill");const timeLabel=document.getElementById("videomarker-time");let previousTime=null;let segmentStart=null;let lastSent=0;let seekingBack=false;adapter.duration().then(duration=>{if(resume&&lastposition>0&&lastposition<duration-2){adapter.seek(lastposition).catch(()=>{})}}).catch(()=>{});const sample=()=>Promise.all([adapter.currentTime(),adapter.duration(),adapter.playing()]).then(([current,duration,playing])=>{if(timeLabel){timeLabel.textContent=`${formatTime(current)} / ${formatTime(duration)}`}if(!allowseek&&!seekingBack&&current>maxwatched+5){seekingBack=true;adapter.seek(maxwatched).finally(()=>{seekingBack=false});previousTime=null;segmentStart=null;return}const now=Date.now();if(playing){const continuous=previousTime!==null&&current>=previousTime&&current-previousTime<=2.5;if(!continuous||segmentStart===null){segmentStart=current}if(now-lastSent>=4e3&&current>=segmentStart&&current-segmentStart<=15){const segmentstart=segmentStart;const segmentend=current;lastSent=now;segmentStart=current;Ajax.call([{methodname:"mod_videomarker_update_progress",args:{cmid:cmid,duration:duration,currenttime:current,segmentstart:segmentstart,segmentend:segmentend}}])[0].then(progress=>{maxwatched=Math.max(maxwatched,Number(progress.maxwatched||0));const percent=Number(progress.percent||0);if(progressValue){progressValue.textContent=`${percent.toFixed(1)}%`}if(progressFill){progressFill.style.width=`${Math.min(100,percent)}%`}}).catch(()=>{})}previousTime=current}else{previousTime=null;segmentStart=null}}).catch(()=>{});adapter.onTime(sample);window.setInterval(sample,1e3);root.querySelectorAll("[data-seek]").forEach(button=>{button.addEventListener("click",()=>adapter.seek(Number(button.dataset.seek||0)).catch(Notification.exception))});root.querySelectorAll(".videomarker-question").forEach(question=>initialiseQuestion(root,question,adapter))}).catch(Notification.exception)};return{init:init}});